#[derive(Hash, Eq, PartialEq, Clone, Debug)]
pub enum Scope {
    All,
    Scoped(String),
}

#[derive(Error, Debug)]
pub enum ScopeParseError {
    #[error("Scope is empty")]
    EmptyScope,
}

impl FromStr for Scope {
    type Err = ScopeParseError;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        match s.trim() {
            "" => Err(ScopeParseError::EmptyScope),
            "*" => Ok(Scope::All),
            scope => Ok(Scope::Scoped(scope.to_string())),
        }
    }
}

#[derive(Hash, Eq, PartialEq, Clone, Debug)]
pub enum DeleteRange {
    MergedLocal,
    MergedRemote(Scope),
    Stray,
    Diverged(Scope),
    MergedNonTrackingLocal,
    MergedNonUpstreamRemoteTracking(Scope),
}

#[derive(Error, Debug)]
pub enum DeleteParseError {
    #[error("Invalid delete range format `{0}`")]
    InvalidDeleteRangeFormat(String),
    #[error("Scope parse error for delete range while parsing scope: {0}")]
    ScopeParseError(#[from] ScopeParseError),
}

impl DeleteRange {
    pub fn parse_one(arg: &str) -> Result<Vec<DeleteRange>, DeleteParseError> {
        let some_pair: Vec<_> = arg.splitn(2, ':').map(str::trim).collect();
        match *some_pair.as_slice() {
            ["merged", remote] => Ok(vec![
                DeleteRange::MergedLocal,
                DeleteRange::MergedRemote(remote.parse()?),
            ]),
            ["merged-local"] => Ok(vec![DeleteRange::MergedLocal]),
            ["merged-remote", remote] => Ok(vec![DeleteRange::MergedRemote(remote.parse()?)]),
            ["stray"] => Ok(vec![DeleteRange::Stray]),
            ["diverged", remote] => Ok(vec![DeleteRange::Diverged(remote.parse()?)]),
            ["local"] => Ok(vec![DeleteRange::MergedNonTrackingLocal]),
            ["remote", remote] => Ok(vec![DeleteRange::MergedNonUpstreamRemoteTracking(
                remote.parse()?,
            )]),
            _ => Err(DeleteParseError::InvalidDeleteRangeFormat(arg.to_owned())),
        }
    }
}

#[derive(Clone, Default, PartialEq, Eq)]
pub struct DeleteFilter(pub HashSet<DeleteRange>);

impl fmt::Debug for DeleteFilter {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_tuple("DeleteFilter").field(&self.0).finish()
    }
}

impl DeleteFilter {
    pub fn merged_origin() -> Self {
        let mut set = HashSet::new();
        set.insert(DeleteRange::MergedLocal);
        set.insert(DeleteRange::MergedRemote(Scope::Scoped("origin".to_owned())));
        DeleteFilter(set)
    }

    pub fn from_iter<I: IntoIterator<Item = DeleteRange>>(iter: I) -> Self {
        DeleteFilter(iter.into_iter().collect())
    }

    pub fn extend(&mut self, other: DeleteFilter) {
        self.0.extend(other.0);
    }

    fn has(&self, range: &DeleteRange) -> bool {
        self.0.contains(range)
    }

    fn scoped_match<F>(&self, remote: &str, f: F) -> bool
    where
        F: Fn(&DeleteRange) -> Option<&Scope>,
    {
        self.0.iter().any(|r| match f(r) {
            Some(Scope::All) => true,
            Some(Scope::Scoped(s)) => s == remote,
            None => false,
        })
    }

    pub fn scan_tracking(&self) -> bool {
        self.0.iter().any(|r| {
            matches!(
                r,
                DeleteRange::MergedLocal
                    | DeleteRange::MergedRemote(_)
                    | DeleteRange::Stray
                    | DeleteRange::Diverged(_)
            )
        })
    }

    pub fn scan_non_tracking_local(&self) -> bool {
        self.has(&DeleteRange::MergedNonTrackingLocal)
    }

    pub fn scan_non_upstream_remote(&self, remote: &str) -> bool {
        self.scoped_match(remote, |r| match r {
            DeleteRange::MergedNonUpstreamRemoteTracking(s) => Some(s),
            _ => None,
        })
    }

    pub fn delete_merged_local(&self) -> bool {
        self.has(&DeleteRange::MergedLocal)
    }

    pub fn delete_stray(&self) -> bool {
        self.has(&DeleteRange::Stray)
    }

    pub fn delete_merged_non_tracking_local(&self) -> bool {
        self.has(&DeleteRange::MergedNonTrackingLocal)
    }

    pub fn delete_merged_remote(&self, remote: &str) -> bool {
        self.scoped_match(remote, |r| match r {
            DeleteRange::MergedRemote(s) => Some(s),
            _ => None,
        })
    }

    pub fn delete_diverged(&self, remote: &str) -> bool {
        self.scoped_match(remote, |r| match r {
            DeleteRange::Diverged(s) => Some(s),
            _ => None,
        })
    }

    pub fn delete_merged_non_upstream_remote(&self, remote: &str) -> bool {
        self.scan_non_upstream_remote(remote)
    }
}

impl FromStr for DeleteFilter {
    type Err = DeleteParseError;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        Ok(DeleteFilter::from_iter(DeleteRange::parse_one(s)?))
    }
}

