/// Finds branches that track `refs/remotes/*/HEAD`.
/// When there is no such local branch, the remote HEADs themselves are used.
fn get_branches_tracks_remote_heads(
    repo: &Repository,
    config: &GitConfig,
) -> Result<HashSet<String>> {
    let mut targets: Vec<String> = Vec::new();
    for remote_name in repo.remotes()?.iter() {
        let remote_name = match remote_name {
            Some(name) => name,
            None => continue,
        };
        let head_name = format!("refs/remotes/{}/HEAD", remote_name);
        let reference = match repo.find_reference(&head_name) {
            Ok(reference) => reference,
            Err(err) if err.code() == ErrorCode::NotFound => continue,
            Err(err) => return Err(err.into()),
        };
        match reference.symbolic_target() {
            Some(target) => targets.push(target.to_owned()),
            None => debug!(
                "Reference {:?} is expected to be an symbolic ref, but it isn't",
                reference.name()
            ),
        }
    }

    let mut result = HashSet::new();
    if targets.is_empty() {
        return Ok(result);
    }

    for branch in repo.branches(Some(git2::BranchType::Local))? {
        let (branch, _) = branch?;
        let refname = match branch.get().name() {
            Some(name) => name.to_owned(),
            None => continue,
        };
        let local = LocalBranch::new(&refname);
        if let Upstream::Tracking { upstream_refname, .. } = get_upstream(repo, config, &local)? {
            if targets.iter().any(|t| *t == upstream_refname) {
                result.insert(local.short_name().to_owned());
            }
        }
    }

    if result.is_empty() {
        for target in targets {
            result.insert(target);
        }
    }
    Ok(result)
}

