use std::io;
use std::process::{Command, ExitStatus, Stdio};

use anyhow::Result;
use log::*;

fn status_error(status: ExitStatus) -> anyhow::Error {
    let code = status.code().unwrap_or(-1);
    io::Error::from_raw_os_error(code).into()
}

/// Runs a git command and captures its output.
pub fn git_output(args: &[&str]) -> Result<String> {
    trace!("> git {}", args.join(" "));
    let output = Command::new("git")
        .args(args)
        .stdin(Stdio::null())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .output()?;
    if !output.status.success() {
        return Err(status_error(output.status));
    }
    let stdout = String::from_utf8_lossy(&output.stdout).into_owned();
    for line in stdout.lines() {
        trace!("| {}", line);
    }
    Ok(stdout)
}

/// Runs a git command with inherited stdio.
fn git_run(args: &[&str], level: Level) -> Result<()> {
    log!(level, "> git {}", args.join(" "));
    let status = Command::new("git").args(args).status()?;
    if !status.success() {
        return Err(status_error(status));
    }
    Ok(())
}

pub fn remote_update(dry_run: bool) -> Result<()> {
    if dry_run {
        info!("> git remote update --prune (dry-run)");
        Ok(())
    } else {
        git_run(&["remote", "update", "--prune"], Level::Info)
    }
}

pub fn ls_remote_head(remote: &str) -> Result<String> {
    git_output(&["ls-remote", "--symref", remote, "HEAD"])
}

pub fn ls_remote_heads(remote: &str) -> Result<String> {
    git_output(&["ls-remote", "--heads", remote])
}

pub fn branch_merged(base: &str, remote: bool) -> Result<Vec<String>> {
    let output = if remote {
        git_output(&["branch", "--format", "%(refname)", "--remote", "--merged", base])?
    } else {
        git_output(&["branch", "--format", "%(refname)", "--merged", base])?
    };
    Ok(output
        .lines()
        .map(|l| l.trim().to_owned())
        .filter(|l| !l.is_empty())
        .collect())
}

pub fn rev_list_cherry_pick(base: &str, target: &str) -> Result<bool> {
    let range = format!("{}...{}", base, target);
    let output = git_output(&[
        "rev-list",
        "--cherry-pick",
        "--right-only",
        "--no-merges",
        "-n1",
        &range,
    ])?;
    Ok(output.trim().is_empty())
}

pub fn worktree_list() -> Result<String> {
    git_output(&["worktree", "list", "--porcelain"])
}

pub fn push_delete(remote: &str, refnames: &[String], dry_run: bool) -> Result<()> {
    let mut args: Vec<&str> = vec!["push", "--delete", "--no-verify"];
    if dry_run {
        args.push("--dry-run");
    }
    args.push(remote);
    for refname in refnames {
        args.push(refname);
    }
    git_run(&args, Level::Trace)
}

pub fn checkout(refname: &str, dry_run: bool) -> Result<()> {
    if dry_run {
        info!("> git checkout {} (dry-run)", refname);
        Ok(())
    } else {
        git_run(&["checkout", refname], Level::Info)
    }
}

pub fn branch_delete(names: &[String], dry_run: bool) -> Result<()> {
    let mut args: Vec<&str> = vec!["branch", "--delete", "--force"];
    for name in names {
        args.push(name);
    }
    if dry_run {
        info!("> git {} (dry-run)", args.join(" "));
        for name in names {
            println!("Delete branch {} (dry run).", name);
        }
        Ok(())
    } else {
        git_run(&args, Level::Info)
    }
}
