use std::collections::HashSet;
use std::sync::Mutex;

use anyhow::Result;
use git2::{ErrorCode, Oid, Repository, Signature};
use log::*;

use crate::branch::{LocalBranch, RemoteTrackingBranch};
use crate::subprocess;

pub struct MergeTracker {
    merged_set: Mutex<HashSet<Oid>>,
}

#[derive(Debug, Clone)]
pub struct MergeState {
    pub merged: bool,
}

fn resolve(repo: &Repository, spec: &str) -> Result<Oid> {
    if let Ok(oid) = Oid::from_str(spec) {
        if spec.len() == 40 {
            return Ok(oid);
        }
    }
    let object = repo.revparse_single(spec)?;
    let commit = object.peel_to_commit()?;
    Ok(commit.id())
}

fn short(oid: &Oid) -> String {
    let s = oid.to_string();
    s[..7].to_owned()
}

impl MergeTracker {
    pub fn with_base_upstreams(
        repo: &Repository,
        base_upstreams: &[RemoteTrackingBranch],
    ) -> Result<Self> {
        info!("Initializing MergeTracker");
        let tracker = MergeTracker {
            merged_set: Mutex::new(HashSet::new()),
        };
        for base in base_upstreams {
            debug!("base_upstream: {:?}", base);
            let base_oid = resolve(repo, &base.refname)?;
            tracker.track_oid(base_oid);

            let merged_locals: HashSet<String> =
                subprocess::branch_merged(&base.refname, false)?.into_iter().collect();
            for refname in merged_locals {
                if !refname.starts_with("refs/") {
                    continue;
                }
                let oid = match resolve(repo, &refname) {
                    Ok(oid) => oid,
                    Err(_) => continue,
                };
                if oid == base_oid {
                    continue;
                }
                debug!("merged_local: {:?}", LocalBranch::new(&refname));
                tracker.track_oid(oid);
            }

            let merged_remotes: HashSet<String> =
                subprocess::branch_merged(&base.refname, true)?.into_iter().collect();
            for refname in merged_remotes {
                if !refname.starts_with("refs/") || refname.ends_with("/HEAD") {
                    continue;
                }
                let oid = match resolve(repo, &refname) {
                    Ok(oid) => oid,
                    Err(_) => continue,
                };
                if oid == base_oid {
                    continue;
                }
                debug!("merged_remote: {:?}", RemoteTrackingBranch::new(&refname));
                tracker.track_oid(oid);
            }
        }
        Ok(tracker)
    }

    fn track_oid(&self, oid: Oid) {
        trace!("track: {}", oid);
        self.merged_set.lock().unwrap().insert(oid);
    }

    fn is_tracked(&self, oid: &Oid) -> bool {
        self.merged_set.lock().unwrap().contains(oid)
    }

    /// `target` is a refname or a commit id
    pub fn check_and_track(&self, repo: &Repository, base: &str, target: &str) -> Result<MergeState> {
        let base_oid = resolve(repo, base)?;
        let target_oid = resolve(repo, target)?;

        if self.is_tracked(&target_oid) {
            debug!("tracked: {} ({})", short(&target_oid), target);
            return Ok(MergeState { merged: true });
        }

        let merge_base = match repo.merge_base(base_oid, target_oid) {
            Ok(merge_base) => merge_base,
            Err(err) if err.code() == ErrorCode::NotFound => {
                debug!("noff merged: ({}) -> {}", target, short(&base_oid));
                return Ok(MergeState { merged: false });
            }
            Err(err) => return Err(err.into()),
        };

        if subprocess::rev_list_cherry_pick(base, target)? {
            debug!("rebase merged: {} -> {}", target, base);
            self.track_oid(target_oid);
            return Ok(MergeState { merged: true });
        }

        let target_commit = repo.find_commit(target_oid)?;
        let merge_base_commit = repo.find_commit(merge_base)?;
        let tree = target_commit.tree()?;
        let sig = Signature::now("git-trim", "git-trim@squash.merge.test.local")?;
        let squashed = repo.commit(
            None,
            &sig,
            &sig,
            "git-trim: squash merge test",
            &tree,
            &[&merge_base_commit],
        )?;
        if subprocess::rev_list_cherry_pick(base, &squashed.to_string())? {
            debug!("squash merged: {} -> {}", target, base);
            self.track_oid(target_oid);
            return Ok(MergeState { merged: true });
        }

        Ok(MergeState { merged: false })
    }
}
