fn classify(
    repo: &Repository,
    merge_tracker: &MergeTracker,
    remote_heads: &[RemoteHead],
    request: &ClassificationRequest,
) -> Result<ClassificationResponse> {
    let mut result = Vec::new();
    let message;
    match request {
        ClassificationRequest::Tracking(req) => {
            let local = merge_tracker.check_and_track(repo, &req.base.refname, &req.local.refname)?;
            let upstream = match &req.upstream {
                Some(upstream) => Some((
                    upstream,
                    merge_tracker.check_and_track(repo, &req.base.refname, &upstream.refname)?,
                )),
                None => None,
            };
            match (local.merged, upstream) {
                (true, Some((upstream, state))) if state.merged => {
                    message = "local & upstream are merged";
                    result.push(ClassifiedBranch::MergedLocal(req.local.clone()));
                    result.push(ClassifiedBranch::MergedRemoteTracking(upstream.clone()));
                }
                (true, Some((upstream, _))) => {
                    message = "local is merged but diverged with upstream";
                    result.push(ClassifiedBranch::DivergedRemoteTracking {
                        local: req.local.clone(),
                        upstream: upstream.clone(),
                    });
                }
                (false, Some((upstream, state))) if state.merged => {
                    message = "upstream is merged, but the local strays";
                    result.push(ClassifiedBranch::Stray(req.local.clone()));
                    result.push(ClassifiedBranch::MergedRemoteTracking(upstream.clone()));
                }
                (false, Some(_)) => {
                    message = "local & upstream are not merged yet";
                }
                (true, None) => {
                    message = "local is merged but remote is gone";
                    result.push(ClassifiedBranch::MergedLocal(req.local.clone()));
                }
                (false, None) => {
                    message = "local is stray but remote is gone";
                    result.push(ClassifiedBranch::Stray(req.local.clone()));
                }
            }
        }
        ClassificationRequest::DirectFetch(req) => {
            let local = merge_tracker.check_and_track(repo, &req.base.refname, &req.local.refname)?;
            let remote_head = remote_heads
                .iter()
                .find(|h| h.remote == req.remote.remote && h.refname == req.remote.refname);
            let remote = match remote_head {
                Some(head) => {
                    match merge_tracker.check_and_track(repo, &req.base.refname, &head.commit) {
                        Ok(state) => Some(state.merged),
                        Err(_) => Some(false),
                    }
                }
                None => None,
            };
            match (local.merged, remote) {
                (true, Some(true)) => {
                    message = "local & remote are merged";
                    result.push(ClassifiedBranch::MergedDirectFetch {
                        local: req.local.clone(),
                        remote: req.remote.clone(),
                    });
                }
                (true, Some(false)) => {
                    message = "local is merged but diverged with remote";
                    result.push(ClassifiedBranch::DivergedDirectFetch {
                        local: req.local.clone(),
                        remote: req.remote.clone(),
                    });
                }
                (false, Some(true)) => {
                    message = "remote is merged, but the local strays";
                    result.push(ClassifiedBranch::Stray(req.local.clone()));
                }
                (false, Some(false)) => {
                    message = "local & remote are not merged yet";
                }
                (true, None) => {
                    message = "local is merged but remote is gone";
                    result.push(ClassifiedBranch::MergedLocal(req.local.clone()));
                }
                (false, None) => {
                    message = "local is stray but remote is gone";
                    result.push(ClassifiedBranch::Stray(req.local.clone()));
                }
            }
        }
        ClassificationRequest::NonTracking(req) => {
            let local = merge_tracker.check_and_track(repo, &req.base.refname, &req.local.refname)?;
            if local.merged {
                message = "non-tracking local is merged";
                result.push(ClassifiedBranch::MergedNonTrackingLocal(req.local.clone()));
            } else {
                message = "non-tracking local is not merged";
            }
        }
        ClassificationRequest::NonUpstream(req) => {
            let remote =
                merge_tracker.check_and_track(repo, &req.base.refname, &req.remote.refname)?;
            if remote.merged {
                message = "non-upstream remote tracking branch is merged";
                result.push(ClassifiedBranch::MergedNonUpstreamRemoteTracking(
                    req.remote.clone(),
                ));
            } else {
                message = "non-upstream remote tracking branch is not merged";
            }
        }
    }
    Ok(ClassificationResponse { message, result })
}

/// Resolves base patterns into base specs.
fn resolve_bases(
    repo: &Repository,
    config: &GitConfig,
    patterns: &[String],
) -> Result<Vec<BaseSpec>> {
    let mut result = Vec::new();
    for pattern in patterns {
        let reference = match repo.resolve_reference_from_short_name(pattern) {
            Ok(reference) => reference,
            Err(err) if err.code() == ErrorCode::NotFound => continue,
            Err(err) => return Err(err.into()),
        };
        let reference = reference.resolve()?;
        let refname = match reference.name() {
            Some(name) => name.to_owned(),
            None => continue,
        };
        if refname.starts_with("refs/heads/") {
            let local = LocalBranch::new(&refname);
            if let Upstream::Tracking {
                upstream_refname,
                exists: true,
            } = get_upstream(repo, config, &local)?
            {
                result.push(BaseSpec::Local {
                    pattern: pattern.clone(),
                    local,
                    upstream: RemoteTrackingBranch::new(&upstream_refname),
                });
            }
        } else if refname.starts_with("refs/remotes/") {
            result.push(BaseSpec::Upstream {
                pattern: pattern.clone(),
                upstream: RemoteTrackingBranch::new(&refname),
            });
        }
    }
    Ok(result)
}

pub struct Branches {
    pub tracking: Vec<(LocalBranch, Option<RemoteTrackingBranch>)>,
    pub direct_fetch: Vec<(LocalBranch, RemoteBranch)>,
    pub non_tracking: Vec<LocalBranch>,
    pub non_upstream: Vec<RemoteTrackingBranch>,
}

pub fn get_branches(repo: &Repository, config: &GitConfig) -> Result<Branches> {
    let mut tracking = Vec::new();
    let mut direct_fetch = Vec::new();
    let mut non_tracking = Vec::new();
    let mut upstreams: HashSet<String> = HashSet::new();

    for branch in repo.branches(Some(BranchType::Local))? {
        let (branch, _) = branch?;
        let refname = match branch.get().name() {
            Some(name) => name.to_owned(),
            None => continue,
        };
        let local = LocalBranch::new(&refname);
        match get_upstream(repo, config, &local)? {
            Upstream::NonTracking => non_tracking.push(local),
            Upstream::Incomplete => {}
            Upstream::Tracking {
                upstream_refname,
                exists,
            } => {
                if exists {
                    upstreams.insert(upstream_refname.clone());
                    tracking.push((local, Some(RemoteTrackingBranch::new(&upstream_refname))));
                } else {
                    tracking.push((local, None));
                }
            }
            Upstream::DirectFetch(remote) => direct_fetch.push((local, remote)),
        }
    }

    let mut non_upstream = Vec::new();
    for branch in repo.branches(Some(BranchType::Remote))? {
        let (branch, _) = branch?;
        let reference = branch.get();
        if reference.symbolic_target().is_some() {
            continue;
        }
        let refname = match reference.name() {
            Some(name) => name.to_owned(),
            None => continue,
        };
        if upstreams.contains(&refname) {
            continue;
        }
        non_upstream.push(RemoteTrackingBranch::new(&refname));
    }

    Ok(Branches {
        tracking,
        direct_fetch,
        non_tracking,
        non_upstream,
    })
}

fn get_remote_heads(direct_fetch: &[(LocalBranch, RemoteBranch)]) -> Result<Vec<RemoteHead>> {
    let mut result = Vec::new();
    for (_, remote_branch) in direct_fetch {
        let output = subprocess::ls_remote_heads(&remote_branch.remote)?;
        for line in output.lines() {
            let mut iter = line.split('\t');
            let commit = match iter.next() {
                Some(c) => c.trim(),
                None => continue,
            };
            let refname = match iter.next() {
                Some(r) => r.trim(),
                None => continue,
            };
            let head = RemoteHead {
                remote: remote_branch.remote.clone(),
                refname: refname.to_owned(),
                commit: commit.to_owned(),
            };
            if !result.contains(&head) {
                result.push(head);
            }
        }
    }
    Ok(result)
}

fn fnmatch(pattern: &str, string: &str) -> bool {
    let pattern = match std::ffi::CString::new(pattern) {
        Ok(p) => p,
        Err(_) => return false,
    };
    let string = match std::ffi::CString::new(string) {
        Ok(s) => s,
        Err(_) => return false,
    };
    unsafe { libc::fnmatch(pattern.as_ptr(), string.as_ptr(), 0) == 0 }
}

fn matches_pattern(pattern: &str, refname: &str, short_name: &str) -> bool {
    fnmatch(pattern, short_name) || fnmatch(pattern, refname)
}

struct Worktree {
    path: String,
    branch: Option<String>,
}

fn get_worktrees() -> Result<Vec<Worktree>> {
    let output = subprocess::worktree_list()?;
    let mut result = Vec::new();
    let mut path: Option<String> = None;
    let mut branch: Option<String> = None;
    for line in output.lines().chain(std::iter::once("")) {
        if line.is_empty() {
            if let Some(p) = path.take() {
                result.push(Worktree {
                    path: p,
                    branch: branch.take(),
                });
            }
            branch = None;
            continue;
        }
        if let Some(p) = line.strip_prefix("worktree ") {
            path = Some(p.to_owned());
        } else if let Some(b) = line.strip_prefix("branch ") {
            branch = Some(b.to_owned());
        }
    }
    Ok(result)
}

fn same_path(a: &str, b: &std::path::Path) -> bool {
    let a = std::path::Path::new(a);
    if a == b {
        return true;
    }
    match (a.canonicalize(), b.canonicalize()) {
        (Ok(a), Ok(b)) => a == b,
        _ => false,
    }
}

pub fn get_trim_plan(
    repo: &Repository,
    config: &GitConfig,
    param: &PlanParam,
) -> Result<TrimPlan> {
    let bases = resolve_bases(repo, config, &param.bases)?;
    trace!("bases: {:#?}", bases);

    let branches = get_branches(repo, config)?;
    debug!("tracking_branches: {:#?}", branches.tracking);
    debug!("direct_fetch_branches: {:#?}", branches.direct_fetch);
    debug!("non_tracking_branches: {:#?}", branches.non_tracking);
    debug!("non_upstream_branches: {:#?}", branches.non_upstream);

    let remote_heads = if param.delete.scan_tracking() {
        get_remote_heads(&branches.direct_fetch)?
    } else {
        Vec::new()
    };
    debug!("remote_heads: {:#?}", remote_heads);

    let base_upstreams: Vec<RemoteTrackingBranch> = {
        let mut v: Vec<RemoteTrackingBranch> = Vec::new();
        for base in &bases {
            if !v.contains(base.upstream()) {
                v.push(base.upstream().clone());
            }
        }
        v
    };
    let merge_tracker = MergeTracker::with_base_upstreams(repo, &base_upstreams)?;

    info!("Enqueue classification requests");
    let mut skipped: HashMap<String, SkipSuggestion> = HashMap::new();
    let filter = param.delete;

    if !filter.scan_tracking() {
        for (local, upstream) in &branches.tracking {
            skipped.insert(local.refname.clone(), SkipSuggestion::Tracking);
            if let Some(upstream) = upstream {
                skipped.insert(upstream.refname.clone(), SkipSuggestion::Tracking);
            }
        }
        for (local, _) in &branches.direct_fetch {
            skipped.insert(local.refname.clone(), SkipSuggestion::Tracking);
        }
    }
    if !filter.scan_non_tracking_local() {
        for local in &branches.non_tracking {
            skipped.insert(local.refname.clone(), SkipSuggestion::NonTracking);
        }
    }

    let mut requests: Vec<ClassificationRequest> = Vec::new();
    for base in &bases {
        let base_upstream = base.upstream();
        if filter.scan_tracking() {
            for (local, upstream) in &branches.tracking {
                requests.push(ClassificationRequest::Tracking(
                    TrackingBranchClassificationRequest {
                        base: base_upstream.clone(),
                        local: local.clone(),
                        upstream: upstream.clone(),
                    },
                ));
            }
            for (local, remote) in &branches.direct_fetch {
                requests.push(ClassificationRequest::DirectFetch(
                    DirectFetchClassificationRequest {
                        base: base_upstream.clone(),
                        local: local.clone(),
                        remote: remote.clone(),
                    },
                ));
            }
        }
        if filter.scan_non_tracking_local() {
            for local in &branches.non_tracking {
                requests.push(ClassificationRequest::NonTracking(
                    NonTrackingBranchClassificationRequest {
                        base: base_upstream.clone(),
                        local: local.clone(),
                    },
                ));
            }
        }
        for remote_tracking in &branches.non_upstream {
            let remote = remote_tracking.to_remote_branch(repo)?;
            if filter.scan_non_upstream_remote(&remote.remote) {
                requests.push(ClassificationRequest::NonUpstream(
                    NonUpstreamBranchClassificationRequest {
                        base: base_upstream.clone(),
                        remote: remote_tracking.clone(),
                    },
                ));
            } else {
                skipped.insert(
                    remote_tracking.refname.clone(),
                    SkipSuggestion::NonUpstream(remote.remote.clone()),
                );
            }
        }
    }
    for (i, request) in requests.iter().enumerate() {
        trace!("Enqueue #{}: {:#?}", i, request);
    }

    info!("Classify {} requests", requests.len());
    let mut to_delete: HashSet<ClassifiedBranch> = HashSet::new();
    for (i, request) in requests.iter().enumerate() {
        let response = classify(repo, &merge_tracker, &remote_heads, request)?;
        debug!("Result #{}: {:#?}", i, response);
        for branch in response.result {
            to_delete.insert(branch);
        }
    }

    // A branch merged into some base should not be regarded as stray or diverged.
    let merged_locals: HashSet<LocalBranch> = to_delete
        .iter()
        .filter_map(|b| match b {
            ClassifiedBranch::MergedLocal(l) => Some(l.clone()),
            _ => None,
        })
        .collect();
    let merged_remotes: HashSet<RemoteTrackingBranch> = to_delete
        .iter()
        .filter_map(|b| match b {
            ClassifiedBranch::MergedRemoteTracking(r) => Some(r.clone()),
            _ => None,
        })
        .collect();
    to_delete.retain(|b| match b {
        ClassifiedBranch::Stray(l) => !merged_locals.contains(l),
        ClassifiedBranch::DivergedRemoteTracking { upstream, .. } => {
            !merged_remotes.contains(upstream)
        }
        _ => true,
    });

    let mut plan = TrimPlan {
        to_delete,
        preserved: Vec::new(),
        skipped,
    };

    // bases
    let upstream_of: HashMap<String, String> = branches
        .tracking
        .iter()
        .filter_map(|(l, u)| u.as_ref().map(|u| (l.refname.clone(), u.refname.clone())))
        .collect();
    plan.preserve(|branch| {
        for base in &bases {
            match base {
                BaseSpec::Local {
                    local, upstream, ..
                } => {
                    if branch.local() == Some(local) || branch.remote_tracking() == Some(upstream)
                    {
                        return Some(("base".to_owned(), true));
                    }
                }
                BaseSpec::Upstream { pattern, upstream } => {
                    if branch.remote_tracking() == Some(upstream) {
                        return Some(("base".to_owned(), true));
                    }
                    if let Some(local) = branch.local() {
                        if upstream_of.get(&local.refname) == Some(&upstream.refname) {
                            return Some((format!("tracks base `{}`", pattern), true));
                        }
                    }
                }
            }
        }
        None
    });

    // protected patterns
    let patterns = param.protected_patterns.clone();
    plan.preserve(|branch| {
        for pattern in &patterns {
            if let Some(local) = branch.local() {
                if matches_pattern(pattern, &local.refname, local.short_name()) {
                    return Some((format!("protected by a pattern `{}`", pattern), false));
                }
            }
            if let Some(remote) = branch.remote_tracking() {
                if matches_pattern(pattern, &remote.refname, remote.short_name()) {
                    return Some((format!("protected by a pattern `{}`", pattern), false));
                }
            }
        }
        None
    });

    // worktrees
    let worktrees = get_worktrees()?;
    let workdir = repo.workdir().map(|p| p.to_path_buf());
    let mut worktree_branches: HashMap<String, String> = HashMap::new();
    for worktree in &worktrees {
        if let Some(workdir) = &workdir {
            let wd = workdir.to_string_lossy();
            let wd = wd.trim_end_matches('/');
            if same_path(&worktree.path, std::path::Path::new(wd)) {
                continue;
            }
        }
        if let Some(branch) = &worktree.branch {
            worktree_branches
                .entry(branch.clone())
                .or_insert_with(|| worktree.path.clone());
        }
    }
    plan.preserve(|branch| {
        if let Some(local) = branch.local() {
            if let Some(path) = worktree_branches.get(&local.refname) {
                return Some((format!("worktree at {}", path), false));
            }
        }
        None
    });

    // delete filter
    let mut filter_result: HashMap<ClassifiedBranch, Option<String>> = HashMap::new();
    for branch in &plan.to_delete {
        let range = branch.required_delete_range(repo, filter)?;
        filter_result.insert(branch.clone(), range);
    }
    plan.preserve(|branch| {
        filter_result
            .get(branch)
            .cloned()
            .flatten()
            .map(|range| (format!("delete range `{}` was not given", range), false))
    });

    // HEAD
    if !param.detach {
        let head_branch = get_head_branch(repo);
        plan.preserve(|branch| {
            if let (Some(local), Some(head)) = (branch.local(), &head_branch) {
                if local.refname == *head {
                    return Some(("HEAD".to_owned(), false));
                }
            }
            None
        });
    }

    Ok(plan)
}

pub fn get_head_branch(repo: &Repository) -> Option<String> {
    let head = repo.find_reference("HEAD").ok()?;
    let target = head.symbolic_target()?;
    if target.starts_with("refs/heads/") {
        Some(target.to_owned())
    } else {
        None
    }
}

impl TrimPlan {
    fn preserve<F>(&mut self, mut f: F)
    where
        F: FnMut(&ClassifiedBranch) -> Option<(String, bool)>,
    {
        let mut kept = Vec::new();
        let mut remaining = HashSet::new();
        for branch in self.to_delete.drain() {
            match f(&branch) {
                Some((reason, base)) => kept.push(Preserved {
                    branch,
                    reason,
                    base,
                }),
                None => {
                    remaining.insert(branch);
                }
            }
        }
        self.to_delete = remaining;
        self.preserved.extend(kept);
    }

    pub fn locals_to_delete(&self) -> Vec<LocalBranch> {
        let mut result: Vec<LocalBranch> = self
            .to_delete
            .iter()
            .filter_map(|b| b.local().cloned())
            .collect();
        result.sort();
        result.dedup();
        result
    }

    pub fn remotes_to_delete(&self, repo: &Repository) -> Result<Vec<RemoteBranch>> {
        let mut result = Vec::new();
        for branch in &self.to_delete {
            if let Some(remote_tracking) = branch.remote_tracking() {
                result.push(remote_tracking.to_remote_branch(repo)?);
            }
            if let Some(remote) = branch.direct_fetch_remote() {
                result.push(remote.clone());
            }
        }
        result.sort();
        result.dedup();
        Ok(result)
    }

    pub fn get_preserved_local(&self, local: &LocalBranch) -> Option<&Preserved> {
        self.preserved
            .iter()
            .find(|p| p.branch.local() == Some(local))
    }

    pub fn get_preserved_remote_tracking(
        &self,
        remote: &RemoteTrackingBranch,
    ) -> Option<&Preserved> {
        self.preserved
            .iter()
            .find(|p| p.branch.remote_tracking() == Some(remote))
    }
}
