fn c_result(ret: libc::c_int) -> io::Result<()> {
    if ret == 0 {
        Ok(())
    } else {
        Err(io::Error::last_os_error())
    }
}

fn read_byte(fd: i32) -> io::Result<Option<u8>> {
    let mut buf = [0u8; 1];
    loop {
        let n = unsafe { libc::read(fd, buf.as_mut_ptr() as *mut libc::c_void, 1) };
        if n < 0 {
            let err = io::Error::last_os_error();
            if err.kind() == io::ErrorKind::Interrupted {
                continue;
            }
            return Err(err);
        }
        if n == 0 {
            return Ok(None);
        }
        return Ok(Some(buf[0]));
    }
}

fn poll_readable(fd: i32, timeout_ms: i32) -> bool {
    let mut pfd = libc::pollfd {
        fd,
        events: libc::POLLIN,
        revents: 0,
    };
    let ret = unsafe { libc::poll(&mut pfd, 1, timeout_ms) };
    ret > 0 && (pfd.revents & libc::POLLIN) != 0
}

fn read_key_impl(fd: i32) -> io::Result<Key> {
    let byte = match read_byte(fd)? {
        Some(b) => b,
        None => return Ok(Key::Other),
    };
    match byte {
        b'\r' | b'\n' => Ok(Key::Enter),
        3 => Err(io::Error::new(io::ErrorKind::Interrupted, "read interrupted")),
        0x1b => {
            // Consume an escape sequence if any.
            if poll_readable(fd, 0) {
                if let Some(b) = read_byte(fd)? {
                    if b == b'[' || b == b'O' {
                        loop {
                            if !poll_readable(fd, 0) {
                                break;
                            }
                            match read_byte(fd)? {
                                Some(c) if (0x40..=0x7e).contains(&c) => break,
                                Some(_) => continue,
                                None => break,
                            }
                        }
                    }
                }
            }
            Ok(Key::Other)
        }
        b if b < 0x80 => Ok(Key::Char(b as char)),
        b => {
            // UTF-8 multibyte character
            let len = if b >= 0xf0 {
                4
            } else if b >= 0xe0 {
                3
            } else {
                2
            };
            let mut bytes = vec![b];
            for _ in 1..len {
                match read_byte(fd)? {
                    Some(c) => bytes.push(c),
                    None => break,
                }
            }
            match String::from_utf8(bytes) {
                Ok(s) => Ok(s.chars().next().map(Key::Char).unwrap_or(Key::Other)),
                Err(_) => Ok(Key::Other),
            }
        }
    }
}

fn read_single_key() -> io::Result<Key> {
    let tty_file;
    let fd = unsafe {
        if libc::isatty(libc::STDIN_FILENO) == 1 {
            libc::STDIN_FILENO
        } else {
            tty_file = OpenOptions::new().read(true).write(true).open("/dev/tty")?;
            tty_file.as_raw_fd()
        }
    };
    let mut termios = std::mem::MaybeUninit::<libc::termios>::uninit();
    c_result(unsafe { libc::tcgetattr(fd, termios.as_mut_ptr()) })?;
    let original = unsafe { termios.assume_init() };
    let mut raw = original;
    unsafe { libc::cfmakeraw(&mut raw) };
    raw.c_oflag = original.c_oflag;
    c_result(unsafe { libc::tcsetattr(fd, libc::TCSADRAIN, &raw) })?;
    let rv = read_key_impl(fd);
    c_result(unsafe { libc::tcsetattr(fd, libc::TCSADRAIN, &original) })?;
    if let Err(ref err) = rv {
        if err.kind() == io::ErrorKind::Interrupted {
            unsafe {
                libc::raise(libc::SIGINT);
            }
        }
    }
    rv
}

fn write_stderr(s: &str) -> io::Result<()> {
    let mut stderr = io::stderr();
    stderr.write_all(s.as_bytes())?;
    stderr.flush()
}

/// Asks a yes/no question, with `no` as the default answer.
pub fn confirm(prompt: &str) -> Result<bool, Error> {
    if unsafe { libc::isatty(libc::STDERR_FILENO) } != 1 {
        return Err(io::Error::new(io::ErrorKind::NotConnected, "not a terminal").into());
    }
    io::stdout().flush()?;
    write_stderr(&format!("{} [y/N] ", prompt))?;
    write_stderr("\x1b[?25l")?;

    let answer = loop {
        match read_single_key()? {
            Key::Char('y') | Key::Char('Y') => break true,
            Key::Char('n') | Key::Char('N') => break false,
            Key::Enter => break false,
            _ => continue,
        }
    };

    write_stderr("\r\x1b[2K")?;
    write_stderr(&format!("{} {}\n", prompt, if answer { "yes" } else { "no" }))?;
    write_stderr("\x1b[?25h")?;
    Ok(answer)
}

