            ClassifiedBranch::MergedRemoteTracking(upstream) => {
                let remote = upstream.to_remote_branch(repo)?;
                merged_remotes.push(remote.to_string());
            }
            ClassifiedBranch::DivergedRemoteTracking { local, upstream } => {
                merged_locals.push(local.short_name().to_owned());
                let remote = upstream.to_remote_branch(repo)?;
                diverged_remotes.push(remote.to_string());
            }
            ClassifiedBranch::MergedNonTrackingLocal(local) => {
                merged_locals.push(format!("{} (non-tracking)", local.short_name()));
            }
            ClassifiedBranch::MergedNonUpstreamRemoteTracking(upstream) => {
                let remote = upstream.to_remote_branch(repo)?;
                merged_remotes.push(format!("{} (non-upstream)", remote));
            }
            ClassifiedBranch::MergedDirectFetch { local, remote }
            | ClassifiedBranch::DivergedDirectFetch { local, remote } => {
                merged_locals.push(local.short_name().to_owned());
                diverged_remotes.push(remote.to_string());
            }
        }
    }

    fn print_section(title: &str, mut items: Vec<String>) {
        if items.is_empty() {
            return;
        }
        items.sort();
        items.dedup();
        println!("{}", title);
        for item in items {
            println!("  - {}", item);
        }
    }
    print_section("Delete merged local branches:", merged_locals);
    print_section("Delete merged remote refs:", merged_remotes);
    print_section("Delete stray local branches:", stray_locals);
    print_section("Delete diverged remote refs:", diverged_remotes);
    Ok(())
}

fn delete_remote_branches(remotes: &[branch::RemoteBranch], dry_run: bool) -> Result<()> {
    let mut per_remote: BTreeMap<String, Vec<String>> = BTreeMap::new();
    for remote in remotes {
        per_remote
            .entry(remote.remote.clone())
            .or_default()
            .push(remote.refname.clone());
    }
    for (remote, refnames) in per_remote {
        subprocess::push_delete(&remote, &refnames, dry_run)?;
    }
    Ok(())
}

fn delete_local_branches(
    repo: &Repository,
    locals: &[LocalBranch],
    detach: bool,
    dry_run: bool,
) -> Result<()> {
    if locals.is_empty() {
        return Ok(());
    }
    if detach {
        if let Some(head) = get_head_branch(repo) {
            if locals.iter().any(|l| l.refname == head) {
                if dry_run {
                    let commit = repo.find_reference(&head)?.peel_to_commit()?;
                    let id = commit.id().to_string();
                    println!("Note: switching to '{}' (dry run)", head);
                    println!("You are in 'detached HED' state... blah blah...");
                    println!(
                        "HEAD is now at {} {} (dry run)",
                        &id[..7],
                        commit.summary().unwrap_or("")
                    );
                } else {
                    subprocess::checkout(&head, dry_run)?;
                }
            }
        }
    }
    let names: Vec<String> = locals.iter().map(|l| l.short_name().to_owned()).collect();
    subprocess::branch_delete(&names, dry_run)?;
    Ok(())
}

