/// Mimics the usage line of unknown argument errors, which includes the argument group.
fn fix_unknown_argument_usage(cmd: &Command, err: &mut clap::Error, argv: &[std::ffi::OsString]) {
    use clap::error::{ContextKind, ContextValue, ErrorKind};
    if err.kind() != ErrorKind::UnknownArgument {
        return;
    }
    let invalid = match err.get(ContextKind::InvalidArg) {
        Some(ContextValue::String(s)) => s.clone(),
        _ => return,
    };
    if !invalid.starts_with("--") {
        return;
    }
    if err.get(ContextKind::Usage).is_none() {
        return;
    }
    let has_suggestion = err.get(ContextKind::SuggestedArg).is_some();
    let with_eq = format!("{}=", invalid);
    let position = argv
        .iter()
        .skip(1)
        .position(|t| {
            let t = t.to_string_lossy();
            t == invalid || t.starts_with(&with_eq)
        })
        .unwrap_or(0);
    let bin = argv
        .first()
        .and_then(|p| std::path::Path::new(p).file_name().map(|s| s.to_string_lossy().into_owned()))
        .unwrap_or_else(|| "git-trim".to_owned());
    let styles = cmd.get_styles();
    let usage = styles.get_usage();
    let literal = styles.get_literal();
    let placeholder = styles.get_placeholder();
    let text = if has_suggestion || position > 0 {
        format!(
            "{}Usage:{} {}{}{} {}<{}>{}",
            usage.render(),
            usage.render_reset(),
            literal.render(),
            bin,
            literal.render_reset(),
            placeholder.render(),
            GROUP_USAGE,
            placeholder.render_reset()
        )
    } else {
        format!(
            "{}Usage:{} {}{}{} [OPTIONS]",
            usage.render(),
            usage.render_reset(),
            literal.render(),
            bin,
            literal.render_reset(),
        )
    };
    err.insert(
        ContextKind::Usage,
        ContextValue::StyledStr(clap::builder::StyledStr::from(text)),
    );
}

